datapath = '/data/study'

# --- L3: outpath = fullfile(datapath, 'derivatives')  [exact]
outpath = os.path.join(datapath, 'derivatives')

# --- L4: subjects = {'sub01', 'sub02', 'sub03'}  [exact]
subjects = ['sub01', 'sub02', 'sub03']

